INSERT INTO `practice_submissions` VALUES (1,'class Solution {\n    public int search(int[] nums, int target) {\n        int left = 0;\n        int right = nums.length - 1;\n\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n\n            if (nums[mid] == target) {\n                return mid;\n            }\n\n            if (nums[mid] < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n\n        return -1;\n    }\n}\n','phone-919931860964@advcoder.com','java','binary-search',_binary '\0','2026-06-16 14:03:03.110095'),(2,'class Solution {\n    public int search(int[] nums, int target) {\n        int left = 0;\n        int right = nums.length - 1;\n\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n\n            if (nums[mid] == target) {\n                return mid;\n            }\n\n            if (nums[mid] < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n\n        return -1;\n    }\n}\n','phone-919931860964@advcoder.com','java','binary-search',_binary '\0','2026-06-16 14:03:48.513652'),(3,'class Solution {\n    public int search(int[] nums, int target) {\n        int left = 0;\n        int right = nums.length - 1;\n\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n\n            if (nums[mid] == target) {\n                return mid;\n            }\n\n            if (nums[mid] < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n\n        return -1;\n    }\n}\n','phone-919931860964@advcoder.com','java','binary-search',_binary '\0','2026-06-16 14:04:02.038112'),(4,'class Solution {\n    public int search(int[] nums, int target) {\n        int left = 0;\n        int right = nums.length - 1;\n\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n\n            if (nums[mid] == target) {\n                return mid;\n            }\n\n            if (nums[mid] < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n\n        return -1;\n    }\n}','phone-919931860964@advcoder.com','java','binary-search',_binary '','2026-06-16 14:07:16.776159'),(5,'class Solution {\n    public int search(int[] nums, int target) {\n        int left = 0;\n        int right = nums.length - 1;\n\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n\n            if (nums[mid] == target) {\n                return mid;\n            }\n\n            if (nums[mid] < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n\n        return -1;\n    }\n}','phone-919931860964@advcoder.com','java','binary-search',_binary '','2026-06-16 14:07:32.710459'),(6,'import java.util.HashMap;\nimport java.util.Map;\n\nclass Solution {\n    public int[] twoSum(int[] nums, int target) {\n        Map<Integer, Integer> map = new HashMap<>();\n\n        for (int i = 0; i < nums.length; i++) {\n            int complement = target - nums[i];\n\n            if (map.containsKey(complement)) {\n                return new int[]{map.get(complement), i};\n            }\n\n            map.put(nums[i], i);\n        }\n\n        return new int[]{};\n    }\n}','phone-919931860964@advcoder.com','java','two-sum',_binary '','2026-06-16 14:15:35.462356'),(7,'import java.util.HashMap;\nimport java.util.Map;\n\nclass Solution {\n    public int[] twoSum(int[] nums, int target) {\n        Map<Integer, Integer> map = new HashMap<>();\n\n        for (int i = 0; i < nums.length; i++) {\n            int complement = target - nums[i];\n\n            if (map.containsKey(complement)) {\n                return new int[]{map.get(complement), i};\n            }\n\n            map.put(nums[i], i);\n        }\n\n        return new int[]{};\n    }\n}','phone-919931860964@advcoder.com','java','two-sum',_binary '','2026-06-16 14:15:42.526258'),(8,'class Solution {\n    public void reverseString(char[] s) {\n        \n    }\n}','vinaytechnicaleh@gmail.com','java','reverse-string',_binary '\0','2026-06-22 14:44:07.525945'),(9,'class Solution {\n    public void reverseString(char[] s) {\n        int left = 0;\n        int right = s.length - 1;\n\n        while (left < right) {\n            char temp = s[left];\n            s[left] = s[right];\n            s[right] = temp;\n\n            left++;\n            right--;\n        }\n    }\n}','vinaytechnicaleh@gmail.com','java','reverse-string',_binary '','2026-06-22 14:49:15.532126'),(10,'class Solution {\n    public void reverseString(char[] s) {\n        int left = 0;\n        int right = s.length - 1;\n\n        while (left < right) {\n            char temp = s[left];\n            s[left] = s[right];\n            s[right] = temp;\n\n            left++;\n            right--;\n        }\n    }\n}','vinaytechnicaleh@gmail.com','java','reverse-string',_binary '','2026-06-22 14:49:26.210437'),(11,'import java.util.HashMap;\n\npublic class TwoSum {\n\n    public static int[] twoSum(int[] nums, int target) {\n        // Store number and its index\n        HashMap<Integer, Integer> map = new HashMap<>();\n\n        for (int i = 0; i < nums.length; i++) {\n            int complement = target - nums[i];\n\n            // Check if the required number already exists\n            if (map.containsKey(complement)) {\n                return new int[]{map.get(complement), i};\n            }\n\n            // Store current number with its index\n            map.put(nums[i], i);\n        }\n\n        // No solution found (as per problem, this case won\'t occur)\n        return new int[]{-1, -1};\n    }\n\n    public static void main(String[] args) {\n        int[] nums1 = {2, 7, 11, 15};\n        int target1 = 9;\n\n        int[] result1 = twoSum(nums1, target1);\n        System.out.println(\"[\" + result1[0] + \", \" + result1[1] + \"]\");\n\n        int[] nums2 = {3, 2, 4};\n        int target2 = 6;\n\n        int[] result2 = twoSum(nums2, target2);\n        System.out.println(\"[\" + result2[0] + \", \" + result2[1] + \"]\");\n    }\n}','vinaykumar860964@gmail.com','java','two-sum',_binary '\0','2026-06-28 09:40:34.500983'),(12,'import java.util.HashMap;\n\nclass Solution {\n    public int[] twoSum(int[] nums, int target) {\n        HashMap<Integer, Integer> map = new HashMap<>();\n\n        for (int i = 0; i < nums.length; i++) {\n            int complement = target - nums[i];\n\n            if (map.containsKey(complement)) {\n                return new int[]{map.get(complement), i};\n            }\n\n            map.put(nums[i], i);\n        }\n\n        return new int[]{-1, -1};\n    }\n}','vinaykumar860964@gmail.com','java','two-sum',_binary '','2026-06-28 09:41:30.216600'),(13,'import java.util.HashMap;\n\nclass Solution {\n    public int[] twoSum(int[] nums, int target) {\n        HashMap<Integer, Integer> map = new HashMap<>();\n\n        for (int i = 0; i < nums.length; i++) {\n            int complement = target - nums[i];\n\n            if (map.containsKey(complement)) {\n                return new int[]{map.get(complement), i};\n            }\n\n            map.put(nums[i], i);\n        }\n\n        return new int[]{-1, -1};\n    }\n}','vinaykumar860964@gmail.com','java','two-sum',_binary '','2026-06-28 09:41:36.691495'),(14,'import java.util.HashMap;\n\nclass Solution {\n    public int[] twoSum(int[] nums, int target) {\n\n        HashMap<Integer, Integer> map = new HashMap<>();\n\n        for (int i = 0; i < nums.length; i++) {\n\n            int complement = target - nums[i];\n\n            if (map.containsKey(complement)) {\n                return new int[]{map.get(complement), i};\n            }\n\n            map.put(nums[i], i);\n        }\n\n        return new int[]{};\n    }\n}','aapkiapnididi.yt@gmail.com','java','two-sum',_binary '','2026-07-26 11:50:32.160647'),(15,'import java.util.HashMap;\n\nclass Solution {\n    public int[] twoSum(int[] nums, int target) {\n\n        HashMap<Integer, Integer> map = new HashMap<>();\n\n        for (int i = 0; i < nums.length; i++) {\n\n            int complement = target - nums[i];\n\n            if (map.containsKey(complement)) {\n                return new int[]{map.get(complement), i};\n            }\n\n            map.put(nums[i], i);\n        }\n\n        return new int[]{};\n    }\n}','aapkiapnididi.yt@gmail.com','java','two-sum',_binary '','2026-07-26 11:50:38.215507'),(16,'import java.util.HashMap;\n\nclass Solution {\n    public int[] twoSum(int[] nums, int target) {\n\n        HashMap<Integer, Integer> map = new HashMap<>();\n\n        for (int i = 0; i < nums.length; i++) {\n\n            int complement = target - nums[i];\n\n            if (map.containsKey(complement)) {\n                return new int[]{map.get(complement), i};\n            }\n\n            map.pt(nums[i], i);\n        }\n\n        return new int[]{};\n    }\n}','aapkiapnididi.yt@gmail.com','java','two-sum',_binary '\0','2026-07-26 11:50:50.337633'),(17,'class Solution {\n    public int[] twoSum(int[] nums, int target) {\n        return 0; // Default Boilerplate\n    }\n}\n\nimport java.util.*;\npublic class Main {\n    public static void main(String[] args) {\n        // Wrapper execution logic\n    }\n}','vinaykumar860964@gmail.com','java','two-sum',_binary '\0','2026-07-30 15:21:44.091374'),(18,'class Solution {\n    public int[] twoSum(int[] a, int t) {\n        var m = new java.util.HashMap<Integer,Integer>();\n        for(int i=0;i<a.length;i++){\n            if(m.containsKey(t-a[i])) return new int[]{m.get(t-a[i]),i};\n            m.put(a[i],i);\n        }\n        return new int[0];\n    }\n}','vinaytechnicaleh@gmail.com','java','two-sum',_binary '','2026-08-09 12:03:08.444654'),(19,'class Solution {\n    public int[] twoSum(int[] a, int t) {\n        var m = new java.util.HashMap<Integer,Integer>();\n        for(int i=0;i<a.length;i++){\n            if(m.containsKey(t-a[i])) return new int[]{m.get(t-a[i]),i};\n            m.put(a[i],i);\n        }\n        return new int[0];\n    }\n}','vinaytechnicaleh@gmail.com','java','two-sum',_binary '','2026-08-09 12:03:16.434433'),(20,'import java.util.HashMap;\n\nclass Solution {\n    public int[] twoSum(int[] nums, int target) {\n        HashMap<Integer, Integer> map = new HashMap<>();\n\n        for (int i = 0; i < nums.length; i++) {\n            int complement = target - nums[i];\n\n            if (map.containsKey(complement)) {\n                return new int[]{map.get(complement), i};\n            }\n\n            map.put(nums[i], i);\n        }\n\n        return new int[]{};\n    }\n}','inogllecompany@gmail.com','java','two-sum',_binary '','2026-08-21 08:13:21.651885'),(21,'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String input = sc.hasNextLine() ? sc.nextLine().trim() : \"\";\n        System.out.println(new Solution().solve(input));\n    }\n}\n\nclass Solution {\n    public String solve(String input) {\n        return input;\n    }\n}','aapkiapnididi.yt@gmail.com','java','best-time-to-buy-and-sell-stock',_binary '','2026-09-21 19:25:25.694854'),(22,'class Solution {\n    public int search(int[] nums, int target) {\n\n        int low = 0;\n        int high = nums.length - 1;\n\n        while (low <= high) {\n\n            int mid = low + (high - low) / 2;\n\n            if (nums[mid] == target) {\n                return mid;\n            }\n\n            if (nums[mid] < target) {\n                // Target is on the right side\n                low = mid + 1;\n            } else {\n                // Target is on the left side\n                high = mid - 1;\n            }\n        }\n\n        return -1;\n    }\n}','vinaykumar860964@gmail.com','java','binary-search',_binary '','2026-09-29 05:51:34.064519'),(23,'import java.util.*;\n\npublic class Main {\n\n    public static void main(String[] args) {\n\n        Scanner sc = new Scanner(System.in);\n\n        String input = sc.hasNextLine() ? sc.nextLine().trim() : \"\";\n\n        System.out.println(new Solution().solve(input));\n    }\n}\n\nclass Solution {\n\n    public String solve(String input) {\n\n        // Remove [ and ]\n        input = input.replace(\"[\", \"\").replace(\"]\", \"\").trim();\n\n        if (input.isEmpty()) {\n            return \"0\";\n        }\n\n        String[] parts = input.split(\",\");\n\n        int minPrice = Integer.MAX_VALUE;\n        int maxProfit = 0;\n\n        for (String part : parts) {\n\n            int price = Integer.parseInt(part.trim());\n\n            // Minimum buying price so far\n            minPrice = Math.min(minPrice, price);\n\n            // Profit if we sell today\n            int profit = price - minPrice;\n\n            maxProfit = Math.max(maxProfit, profit);\n        }\n\n        return String.valueOf(maxProfit);\n    }\n}','vinaykumar860964@gmail.com','java','best-time-to-buy-and-sell-stock',_binary '\0','2026-09-29 06:53:39.342305'),(24,'import java.util.*;\n\npublic class Main {\n\n    public static void main(String[] args) {\n\n        Scanner sc = new Scanner(System.in);\n\n        String input = sc.hasNextLine() ? sc.nextLine().trim() : \"\";\n\n        System.out.println(new Solution().solve(input));\n    }\n}\n\nclass Solution {\n\n    public String solve(String input) {\n\n        // If input is not a stock-price array, return it unchanged\n        if (!input.matches(\".*\\\\d.*\")) {\n            return input;\n        }\n\n        input = input.replace(\"[\", \"\")\n                     .replace(\"]\", \"\")\n                     .trim();\n\n        String[] parts = input.split(\",\");\n\n        int minPrice = Integer.MAX_VALUE;\n        int maxProfit = 0;\n\n        for (String part : parts) {\n\n            int price = Integer.parseInt(part.trim());\n\n            minPrice = Math.min(minPrice, price);\n\n            int profit = price - minPrice;\n\n            maxProfit = Math.max(maxProfit, profit);\n        }\n\n        return String.valueOf(maxProfit);\n    }\n}','vinaykumar860964@gmail.com','java','best-time-to-buy-and-sell-stock',_binary '','2026-09-29 06:55:04.323398');
